package io.knowledgebrain.space;
import java.nio.file.*;import java.nio.charset.StandardCharsets;import java.time.*;import java.util.*;
import org.apache.kafka.clients.consumer.*;import org.apache.kafka.common.serialization.*;import org.junit.jupiter.api.Test;import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;import org.postgresql.ds.PGSimpleDataSource;import org.springframework.jdbc.core.JdbcTemplate;import static org.assertj.core.api.Assertions.*;
@EnabledIfEnvironmentVariable(named="BRAIN_TEST_GROUP_MEMBERSHIP_KAFKA",matches=".+")
class GroupMembershipKafkaIntegrationTest {
 @Test void realCdcCarriesSecretFreeSnapshotsAndStableReplay()throws Exception{var source=new PGSimpleDataSource();source.setURL(System.getenv("BRAIN_TEST_SPACE_DATABASE_URL"));source.setUser("brain_space");source.setPassword(System.getenv("BRAIN_TEST_SPACE_DATABASE_PASSWORD"));var ids=new UuidV7(Clock.systemUTC());var owner=ids.next();var actor=ids.next();var group=ids.next();var trace="a".repeat(32);var space=new GroupSpaceStore(source,Clock.systemUTC()).provision(group,owner,trace).spaceId();var store=new GroupMembershipStore(source,Clock.systemUTC(),new GroupInvitationCodes(Base64.getUrlEncoder().withoutPadding().encodeToString(new byte[32])));var first=store.issue(group,owner,UUID.randomUUID().toString().replace("-",""),"MEMBER",trace);store.accept(actor,first.code(),trace);store.change(group,owner,actor,1,"VIEWER",trace);store.retire(group,owner,actor,2,false,trace);var second=store.issue(group,owner,UUID.randomUUID().toString().replace("-",""),"VIEWER",trace);store.revoke(group,owner,second.invitation().invitationId(),1,trace);var jdbc=new JdbcTemplate(source);var expected=new HashMap<String,byte[]>();for(var row:jdbc.queryForList("SELECT id,payload FROM outbox_event WHERE aggregateid IN (?,?,?) AND aggregatetype IN ('group-invitation','group-membership')",space,first.invitation().invitationId(),second.invitation().invitationId()))expected.put(row.get("id").toString(),(byte[])row.get("payload"));assertThat(expected).hasSize(7);
 var p=new Properties();p.put("bootstrap.servers",System.getenv("BRAIN_TEST_GROUP_MEMBERSHIP_KAFKA"));p.put("group.id","group-validation-"+UUID.randomUUID());p.put("enable.auto.commit","false");p.put("auto.offset.reset","earliest");p.put("key.deserializer",StringDeserializer.class.getName());p.put("value.deserializer",ByteArrayDeserializer.class.getName());p.put("security.protocol","SSL");p.put("ssl.endpoint.identification.algorithm","HTTPS");p.put("ssl.truststore.type","PEM");p.put("ssl.keystore.type","PEM");p.put("ssl.truststore.certificates",Files.readString(Path.of("/group-kafka-test/ca.crt")));p.put("ssl.keystore.certificate.chain",Files.readString(Path.of("/group-kafka-test/user.crt")));p.put("ssl.keystore.key",Files.readString(Path.of("/group-kafka-test/user.key")));
 for(int replay=0;replay<2;replay++){var seen=new HashSet<String>();try(var consumer=new KafkaConsumer<String,byte[]>(p)){consumer.subscribe(List.of("space.group-invitation.v1","space.group-membership.v1"));var deadline=System.nanoTime()+Duration.ofSeconds(60).toNanos();while(seen.size()<expected.size()&&System.nanoTime()<deadline)for(var record:consumer.poll(Duration.ofMillis(300))){var e=io.knowledgebrain.contracts.space.group.invitation.v1.EventEnvelopeV1.parseFrom(record.value());if(!expected.containsKey(e.getEventId()))continue;assertThat(record.value()).isEqualTo(expected.get(e.getEventId()));assertThat(record.key()).isEqualTo(e.getAggregateId());assertThat(e.getSpaceId()).isEqualTo(space.toString());assertThat(new String(record.value(),StandardCharsets.ISO_8859_1)).doesNotContain(first.code(),second.code());var h=new HashMap<String,String>();record.headers().forEach(x->h.put(x.key(),new String(x.value(),StandardCharsets.UTF_8)));assertThat(h).containsEntry("id",e.getEventId()).containsEntry("trace_id",trace).containsEntry("schema_group","space").containsEntry("schema_version","1").containsEntry("schema_artifact",record.topic().contains("invitation")?"group-invitation-events":"group-membership-events");seen.add(e.getEventId());}}assertThat(seen).containsAll(expected.keySet());}
 System.out.println("PASS actual invitation/membership CDC: seven byte-exact snapshots, no credentials, stable unacknowledged replay and trace/schema headers");}
}
